mapper.select:
SELECT EXISTS (
    SELECT 1
    FROM chat_message m
    JOIN chat_room r ON r.room_id = m.room_id
    WHERE m.is_read = 0
      AND m.sender_id != #{userId}
      AND (
            r.buyer_id = #{userId}
         OR r.seller_id = #{userId}
      )
)

SELECT r.room_id AS roomId,
/* ========================= 상대방 정보 (DTO 필드명에 맞춤) ========================= */ CASE WHEN r.buyer_id = #{userId} THEN s.user_id ELSE b.user_id END AS opponentUserId,
CASE WHEN r.buyer_id = #{userId} THEN s.nickname ELSE b.nickname END AS opponentNickName,
CASE WHEN r.buyer_id = #{userId} THEN s.profile_img ELSE b.profile_img END AS opponentProfileImg,
/* ========================= 마지막 메시지 ========================= */ lm.content AS lastMessage, lm.created_at AS lastSentAt,
/* ========================= 안 읽은 메시지 수 (서브쿼리) ========================= */ ( SELECT COUNT(*) FROM chat_message m WHERE m.room_id = r.room_id AND m.is_read = 0 AND m.sender_id != #{userId} ) AS unreadCount
FROM chat_room r
JOIN users b ON b.user_id = r.buyer_id JOIN users s ON s.user_id = r.seller_id
/* 마지막 메시지 */ LEFT JOIN chat_message lm ON lm.message_id = ( SELECT message_id FROM chat_message WHERE room_id = r.room_id ORDER BY created_at DESC LIMIT 1 )
WHERE r.buyer_id = #{userId} OR r.seller_id = #{userId}
HAVING unreadCount > 0
ORDER BY lm.created_at DESC

SELECT cr.room_id AS roomId, cr.product_id AS productId, cr.room_type AS roomType,
/* ========================= 상대방 기본 정보 ========================= */ CASE WHEN cr.buyer_id = #{loginUserId} THEN seller.user_id ELSE buyer.user_id END AS opponentUserId,
CASE WHEN cr.buyer_id = #{loginUserId} THEN seller.nickname ELSE buyer.nickname END AS opponentUserNickName,
CASE WHEN cr.buyer_id = #{loginUserId} THEN seller.profile_img ELSE buyer.profile_img END AS opponentProfileImg,
/* ========================= 상대방 신뢰도 (seller_profile) ========================= */ COALESCE(sp.rating_avg, 0.0) AS opponentRatingAvg, COALESCE(sp.total_reviews, 0) AS opponentTotalReviews,
/* ========================= 상품 정보 - ADMIN_DM 인 경우 NULL ========================= */ p.product_name AS productName, p.price AS productPrice,
/* ========================= 채팅방 상태 ========================= */ cr.room_status AS roomStatusCode, CASE cr.room_status WHEN 'ACTIVE' THEN '진행중' WHEN 'CLOSED' THEN '종료됨' END AS roomStatusLabel
FROM chat_room cr JOIN users buyer ON cr.buyer_id = buyer.user_id JOIN users seller ON cr.seller_id = seller.user_id
/* 상대방 기준 seller_profile */ LEFT JOIN seller_profile sp ON sp.seller_id = ( CASE WHEN cr.buyer_id = #{loginUserId} THEN seller.user_id ELSE buyer.user_id END )
/* 상품 (★ LEFT JOIN 으로 변경) */ LEFT JOIN products p ON p.product_id = cr.product_id
WHERE cr.room_id = #{roomId}

SELECT cm.message_id AS messageId, cm.room_id AS roomId, cm.sender_id AS senderUserId, cm.content AS content,
/* 메시지 타입 */ cm.message_type AS messageTypeCode, CASE cm.message_type WHEN 'TEXT' THEN '텍스트' WHEN 'IMAGE' THEN '이미지' END AS messageTypeLabel,
cm.is_read AS isRead, cm.created_at AS createdAt
FROM chat_message cm
WHERE cm.room_id = #{roomId}
ORDER BY cm.created_at ASC
